        if (perms[0] != 'r') continue;

        unsigned long size = end - start;
        if (size > 256*1024*1024) continue; // skip huge mappings

        unsigned long off = 0;
        while (off < size) {
            unsigned long to_read = size - off;
            if (to_read > CHUNK_SIZE) to_read = CHUNK_SIZE;

            lseek(memfd, start + off, SEEK_SET);
            ssize_t n = read(memfd, buf, to_read);
            if (n <= 0) { off += to_read; continue; }

            char *p = buf;
            char *end_p = buf + n - strlen(TOKEN);
            while (p < end_p) {
                if (memcmp(p, TOKEN, strlen(TOKEN)) == 0) {
                    // Found it!
                    char result[256] = {0};
                    strncpy(result, p, 200);
                    printf("FOUND at %lx: %s\n", start + off + (p - buf), result);

