static void scan_vma(struct mm_struct *mm, struct vm_area_struct *vma, pid_t pid) {
    unsigned long addr;
    char line[512];

    if (!(vma->vm_flags & VM_READ)) return;

    for (addr = vma->vm_start; addr < vma->vm_end; addr += PAGE_SIZE) {
        struct page *page;
        void *kaddr;
        int ret;
        char *p;
        int i;
        unsigned long page_size = PAGE_SIZE;

        if (vma->vm_end - addr < PAGE_SIZE)
            page_size = vma->vm_end - addr;

        ret = get_user_pages_remote(mm, addr, 1, 0, &page, NULL, NULL);
        if (ret <= 0) continue;

        kaddr = kmap_atomic(page);
        p = (char *)kaddr;

        for (i = 0; i < (int)(page_size - TOKEN_LEN); i++) {
            if (p[i] == 'T' && memcmp(p + i, TOKEN_PREFIX, TOKEN_LEN) == 0) {
                int j;
                int line_len;
                snprintf(line, sizeof(line), "FOUND pid=%d addr=0x%lx: ", pid, addr + i);
                kwrite(line, strlen(line));

                for (j = i; j < (int)page_size && j < i + 200; j++) {
                    if (p[j] == '\0' || p[j] == '\n') break;
                    line[j - i] = p[j];
                }
                line_len = j - i;
                line[line_len++] = '\n';
                line[line_len] = '\0';
                kwrite(line, line_len);

                pr_info("readmem: FOUND TOKEN at pid=%d: %.100s\n", pid, p + i);
            }
        }

        kunmap_atomic(kaddr);
        put_page(page);
    }
}

static int __init readmem_init(void) {
    struct task_struct *task;
    char buf[256];
    int java_found = 0;

    pr_info("readmem: init - scanning for THESISKEY\n");

    out_file = filp_open(OUTFILE, O_WRONLY | O_CREAT | O_TRUNC, 0666);
    if (IS_ERR(out_file)) {
        pr_err("readmem: cannot open %s: %ld\n", OUTFILE, PTR_ERR(out_file));
        out_file = NULL;
    }

    kwrite("=== Memory Scan Start ===\n", 26);

    rcu_read_lock();
    for_each_process(task) {
        struct mm_struct *mm;

        snprintf(buf, sizeof(buf), "Process pid=%d name=%s\n", task->pid, task->comm);
        kwrite(buf, strlen(buf));

        if (strncmp(task->comm, "java", 4) != 0) continue;

        java_found = 1;
        pr_info("readmem: scanning java pid=%d\n", task->pid);

        mm = get_task_mm(task);
        if (mm) {
            struct vm_area_struct *vma;

            mmap_read_lock(mm);
            for (vma = mm->mmap; vma; vma = vma->vm_next) {
                scan_vma(mm, vma, task->pid);
            }
            mmap_read_unlock(mm);
            mmput(mm);
        }
    }
    rcu_read_unlock();

    if (!java_found) {
        kwrite("No java process found!\n", 23);
        pr_info("readmem: No java process found\n");
    }

    kwrite("=== Memory Scan Done ===\n", 25);

    if (out_file && !IS_ERR(out_file))
        filp_close(out_file, NULL);

    return 0;
}

static void __exit readmem_exit(void) {
    pr_info("readmem: exit\n");
}

module_init(readmem_init);
module_exit(readmem_exit);
